const state={lesson:lessons[0],step:0,mode:'learn',open:new Set([modules[0].id]),done:new Set(store.get('done',[])),solved:new Set(store.get('solved',[])),paused:false,resultView:false,result:null,sourceCount:0,renderToken:0,searchIndex:0,filter:'all',labSQL:store.get('draft','SELECT name, price\nFROM products\nWHERE price < 50\nORDER BY price;')};
